import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    factorials = []
    f = 1
    d = 0
    while f <= 10**12 + 1000:
        factorials.append(f)
        d += 1
        f *= d

    powers_of_two = []
    p = 1
    while p <= 10**12 + 1000:
            powers_of_two.append(p)
            p *= 2

    powerful_set = set(factorials)
    for p_val in powers_of_two:
        powerful_set.add(p_val)

    powerful_list = sorted(list(powerful_set))

    results = []

    for _ in range(t):
        try:
            n_str = next(iterator)
            n = int(n_str)
        except StopIteration:
            break

        if n in powerful_set:
            results.append("1")
            continue

        found = False
        ans = float('inf')

        for f_val in factorials:
            if f_val >= n:
                break

            rem = n - f_val
            if rem in powerful_set:
                if rem != f_val:
                    ans = min(ans, 2)
                    found = True

        if found:
            results.append(str(ans))
            continue

        found_3 = False
        for i, f_val in enumerate(factorials):
            if f_val >= n:
                break

            for j in range(i + 1, len(factorials)):
                f2 = factorials[j]
                if f_val + f2 >= n:
                    break

                rem = n - f_val - f2
                if rem in powerful_set:
                    if rem != f_val and rem != f2:
                        found_3 = True
                        break
            if found_3:
                break

        if found_3:
            results.append("3")
        else:
            results.append("-1")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
